export interface SaintOfDay {
  name: string;
  feastDate: string;
  shortBio: string;
  struggles: string[];
  quote?: string;
  companionId?: string;
}

export const SAINTS: SaintOfDay[] = [
  { name: 'St. Thomas Aquinas', feastDate: '01-28', shortBio: 'The Dominican friar who married faith and reason. His Summa Theologica is the greatest intellectual cathedral of the Middle Ages — and he called it all "straw" after a mystical vision.', struggles: ['Doubt', 'Intellectual pride', 'Big questions'], quote: 'To one who has faith, no explanation is necessary. To one without faith, no explanation is possible.' },
  { name: 'St. John Bosco', feastDate: '01-31', shortBio: 'A priest who dedicated his life to troubled youth, founding schools and orphanages for boys others had given up on. He believed in reason, religion, and kindness above punishment.', struggles: ['Fatherhood', 'Mentoring', 'Troubled youth', 'Patience'] },
  { name: 'St. Maximilian Kolbe', feastDate: '08-14', shortBio: 'A Franciscan friar who volunteered to die in place of a stranger at Auschwitz. He had struggled with addiction to nicotine and a temper — and still became a martyr of charity.', struggles: ['Addiction', 'Self-sacrifice', 'Anger', 'Temper'], companionId: 'paul' },
  { name: 'St. Augustine', feastDate: '08-28', shortBio: 'A philosopher, partygoer, and seeker who chased pleasure for years before his mother\'s prayers and a Bible verse brought him to his knees. The greatest convert in Church history.', struggles: ['Addiction', 'Lust', 'Restlessness', 'Intellectual pride', 'Doubt'], quote: 'Our hearts are restless until they rest in You.', companionId: 'david' },
  { name: 'St. Monica', feastDate: '08-27', shortBio: 'A mother who prayed for her wayward son Augustine for 17 years without giving up. She wept, she hoped, and she never stopped interceding.', struggles: ['Family', 'Wayward children', 'Perseverance', 'Grief'] },
  { name: 'St. Padre Pio', feastDate: '09-23', shortBio: 'A Capuchin friar who bore the stigmata for 50 years, heard confessions for hours daily, and could read souls. He suffered physically and spiritually — and never stopped serving.', struggles: ['Suffering', 'Exhaustion', 'Doubt', 'Spiritual warfare'], quote: 'Pray, hope, and don\'t worry.' },
  { name: 'St. Francis of Assisi', feastDate: '10-04', shortBio: 'A rich young man who stripped naked in the town square, renounced his inheritance, and rebuilt the Church one stone at a time. He talked to birds and tamed wolves.', struggles: ['Wealth', 'Identity', 'Simplicity', 'Calling'], companionId: 'ignatius' },
  { name: 'St. Thérèse of Lisieux', feastDate: '10-01', shortBio: 'A cloistered Carmelite who died at 24 and taught the "Little Way" — doing small things with great love. She struggled with darkness and dryness in prayer but never gave up.', struggles: ['Depression', 'Smallness', 'Doubt', 'Perseverance'], quote: 'Miss no single opportunity of making some small sacrifice.', companionId: 'therese' },
  { name: 'St. Ignatius of Loyola', feastDate: '07-31', shortBio: 'A soldier whose leg was shattered by a cannonball. In recovery, he read about the saints and was converted. He gave us the Spiritual Exercises and the rules of discernment.', struggles: ['Discernment', 'Ambition', 'Ego', 'Vocation'], companionId: 'ignatius' },
  { name: 'St. Benedict', feastDate: '07-11', shortBio: 'A young man who fled corrupt Rome for a cave in the mountains. He founded monasteries and gave the West its rule of prayer and work — ora et labora.', struggles: ['Stability', 'Discipline', 'Overwhelm', 'Community'], companionId: 'ignatius' },
  { name: 'St. Teresa of Avila', feastDate: '10-15', shortBio: 'A Carmelite reformer and mystic who wrote the Interior Castle. She battled illness, opposition, and her own convents — and became a Doctor of the Church.', struggles: ['Burnout', 'Opposition', 'Prayer', 'Reform'], quote: 'Let nothing disturb you, let nothing frighten you. All things pass away: God never changes.' },
  { name: 'St. John of the Cross', feastDate: '12-14', shortBio: 'A Carmelite mystic and poet who was imprisoned by his own brothers in a dark cell for months. He wrote the Dark Night of the Soul in that darkness.', struggles: ['Depression', 'Darkness', 'Isolation', 'Spiritual dryness'], quote: 'He who climbs never stops going from beginning to beginning.' },
  { name: 'St. Anthony of the Desert', feastDate: '01-17', shortBio: 'The first monk. He heard "go, sell what you have" in church and took it literally — living in the Egyptian desert for decades, battling demons and finding God in silence.', struggles: ['Temptation', 'Simplicity', 'Solitude', 'Spiritual warfare'], quote: 'Expect temptation until your last breath.' },
  { name: 'St. John Vianney', feastDate: '08-04', shortBio: 'A parish priest who barely passed seminary but became the patron of parish priests. He spent 16-18 hours a day in the confessional and battled the devil physically.', struggles: ['Inadequacy', 'Imposter syndrome', 'Exhaustion', 'Spiritual warfare'], quote: 'The man who is full of himself is empty of God.' },
  { name: 'St. Teresa of Calcutta', feastDate: '09-05', shortBio: 'A tiny nun who picked up the dying from the streets of Calcutta. She experienced decades of spiritual darkness — feeling God\'s absence — and served anyway.', struggles: ['Doubt', 'Darkness', 'Burnout', 'Suffering', 'Poverty'], quote: 'Do small things with great love.' },
  { name: 'St. John Paul II', feastDate: '10-22', shortBio: 'The pope who survived an assassination attempt, helped bring down communism, and wrote more encyclicals than any pope in history. He lost his entire family by age 20.', struggles: ['Grief', 'Loss', 'Leadership', 'Doubt'], quote: 'Do not be afraid. Do not be satisfied with mediocrity.' },
  { name: 'St. Thomas More', feastDate: '06-22', shortBio: 'A lawyer, father, and Lord Chancellor who chose death over betraying his conscience. Henry VIII had him executed. He was cheerful to the scaffold.', struggles: ['Conscience', 'Integrity', 'Career vs. faith', 'Fatherhood'], quote: 'I die the king\'s good servant, but God\'s first.' },
  { name: 'St. Francis de Sales', feastDate: '01-24', shortBio: 'A gentle bishop who won back thousands of Calvinists to the faith through kindness, not argument. He wrote Introduction to the Devout Life for ordinary laypeople.', struggles: ['Anger', 'Patience', 'Gentleness', 'Everyday holiness'], quote: 'Have patience with all things, but chiefly have patience with yourself.' },
  { name: 'St. Bernard of Clairvaux', feastDate: '08-20', shortBio: 'A Cistercian abbot who preached the Second Crusade, advised popes, and wrote luminous sermons on the Song of Songs. He was a man of tears and fire.', struggles: ['Emotion', 'Zeal', 'Disappointment', 'Leadership'], quote: 'Tears are the wine of the soul.' },
  { name: 'St. Catherine of Siena', feastDate: '04-29', shortBio: 'A Dominican tertiary who counseled popes and cared for the dying. She was a mystic, a reformer, and a woman who spoke truth to power in a man\'s world.', struggles: ['Boldness', 'Reform', 'Suffering', 'Vocation'], quote: 'Be who God meant you to be and you will set the world on fire.' },
  { name: 'St. Anthony of Padua', feastDate: '06-13', shortBio: 'A Franciscan preacher known for his eloquence and his love of the poor. He is the patron of lost things — because he always found what was missing.', struggles: ['Lostness', 'Preaching', 'Poverty', 'Temper'], quote: 'The greater the struggle, the greater the grace.' },
  { name: 'St. Basil the Great', feastDate: '01-02', shortBio: 'A bishop who built hospitals, defended the faith against heresy, and wrote the rule of life still followed by Eastern monks. He was a man of discipline and compassion.', struggles: ['Discipline', 'Fasting', 'Justice', 'Overwhelm'], quote: 'Fasting is the medicine of the soul.' },
  { name: 'St. John Chrysostom', feastDate: '09-13', shortBio: 'The "golden-mouthed" preacher of Constantinople. He spoke truth to the empress and was exiled for it. He died on the road, still preaching.', struggles: ['Speaking truth', 'Exile', 'Injustice', 'Courage'], quote: 'No one can harm the man who does not harm himself.' },
  { name: 'St. Faustina Kowalska', feastDate: '10-05', shortBio: 'A Polish nun who received visions of Jesus as Divine Mercy. She was uneducated, sickly, and ignored — and she wrote a diary that changed the Church.', struggles: ['Sickness', 'Rejection', 'Smallness', 'Trust'], quote: 'The soul that recommends itself to Me will not perish.' },
  { name: 'St. Joseph', feastDate: '03-19', shortBio: 'The quiet foster father of Jesus. A carpenter, a husband, a protector. He speaks no recorded word in Scripture — and he is the patron of the universal Church.', struggles: ['Fatherhood', 'Marriage', 'Work pressure', 'Protecting family'], companionId: 'joseph' },
  { name: 'St. Paul', feastDate: '06-29', shortBio: 'The persecutor turned apostle. Beaten, shipwrecked, imprisoned — and still running the race. He wrote half the New Testament from prison cells.', struggles: ['Addiction', 'Discipline', 'Endurance', 'Changing direction'], companionId: 'paul' },
  { name: 'St. Peter', feastDate: '06-29', shortBio: 'The fisherman who walked on water and sank, who denied Christ and was restored. The rock the Church was built on — a flawed man chosen anyway.', struggles: ['Failure', 'Impulsivity', 'Starting over', 'Self-doubt'], companionId: 'peter' },
  { name: 'St. John the Baptist', feastDate: '06-24', shortBio: 'The forerunner who ate locusts in the desert and pointed to the Lamb. He decreased so Christ could increase — and lost his head for speaking truth.', struggles: ['Simplicity', 'Ego', 'Discipline', 'Doubt'], companionId: 'paul' },
  { name: 'St. Michael the Archangel', feastDate: '09-29', shortBio: 'The warrior angel who cast Satan from heaven. He is the patron of soldiers, police, and anyone in spiritual battle. "Who is like God?"', struggles: ['Spiritual warfare', 'Protection', 'Courage', 'Fear'] },
  { name: 'St. Jude Thaddeus', feastDate: '10-28', shortBio: 'The patron of lost causes. He is the saint you pray to when everything is hopeless — because he knows what it means to be forgotten and still faithful.', struggles: ['Hopelessness', 'Despair', 'Lost causes', 'Feeling forgotten'] },
  { name: 'St. Christopher', feastDate: '07-25', shortBio: 'The patron of travelers. He carried the Christ Child across a river and felt the weight of the world. He is the saint for the journey.', struggles: ['Journey', 'Transition', 'Protection', 'Moving'] },
  { name: 'St. Raphael the Archangel', feastDate: '09-29', shortBio: 'The healing angel from the Book of Tobit. He is the patron of healing, travelers, and those seeking a spouse.', struggles: ['Healing', 'Loneliness', 'Journey', 'Sickness'] },
  { name: 'St. Luke', feastDate: '10-18', shortBio: 'A physician, painter, and the author of the Gospel of Luke and Acts. He was a companion of Paul and wrote the most beautiful parables — the Prodigal Son, the Good Samaritan.', struggles: ['Healing', 'Art', 'Companionship', 'Detail'] },
  { name: 'Sts. Jean de Brébeuf & Isaac Jogues', feastDate: '10-19', shortBio: 'French Jesuit missionaries who brought the Gospel to the Huron and Iroquois peoples of North America. Brébeuf was tortured and killed; Jogues lost fingers to captivity and returned anyway. They are the patron saints of Canada.', struggles: ['Perseverance', 'Suffering', 'Mission', 'Courage'], quote: 'My God, I do not ask for the goods of this world.' },
  { name: 'St. Mark', feastDate: '04-25', shortBio: 'The Gospel writer who was Peter\'s interpreter and Paul\'s failed companion. He quit the first missionary journey — and came back. His Gospel is the shortest and most urgent.', struggles: ['Failure', 'Starting over', 'Urgency'], companionId: 'peter' },
  { name: 'St. Matthew', feastDate: '09-21', shortBio: 'A tax collector — a collaborator, a traitor to his people — who Jesus called from the counting table. He wrote the Gospel for a Jewish audience.', struggles: ['Greed', 'Betrayal', 'Conversion', 'Money'], companionId: 'david' },
  { name: 'All Saints', feastDate: '11-01', shortBio: 'The feast of everyone who made it home — the known and the unknown, the famous and the forgotten. The cloud of witnesses cheering you on.', struggles: ['Loneliness', 'Isolation', 'Feeling forgotten'] },
  { name: 'All Souls', feastDate: '11-02', shortBio: 'The feast of the faithful departed. We pray for those who have gone before us, and we remember that death does not sever the bond of love.', struggles: ['Grief', 'Loss', 'Death', 'Remembrance'] },
  { name: 'St. Nicholas', feastDate: '12-06', shortBio: 'A bishop who punched a heretic at the Council of Nicaea and secretly gave gold to poor girls so they could marry. The real Santa Claus was a fighter.', struggles: ['Generosity', 'Justice', 'Children', 'Courage'] },
  { name: 'St. Lucy', feastDate: '12-13', shortBio: 'A young Sicilian martyr who consecrated her virginity and was killed for it. She is the patron of the blind and those in darkness — her name means light.', struggles: ['Purity', 'Darkness', 'Courage', 'Youth'] },
  { name: 'St. Ambrose', feastDate: '12-07', shortBio: 'The bishop who baptized Augustine. He was a governor, not a priest, when the people seized him and made him bishop by acclamation. He sang the Church into beauty.', struggles: ['Leadership', 'Unexpected calling', 'Music', 'Courage'] },
  { name: 'St. Stephen', feastDate: '12-26', shortBio: 'The first martyr. He was a deacon who preached and was stoned to death — with a young man named Saul holding the coats. He forgave his killers as he died.', struggles: ['Forgiveness', 'Martyrdom', 'Injustice', 'Courage'] },
  { name: 'St. John the Evangelist', feastDate: '12-27', shortBio: 'The beloved disciple who leaned on Jesus at the Last Supper. He wrote the Gospel of love, three epistles, and the Book of Revelation. He was the only apostle at the cross.', struggles: ['Love', 'Loneliness', 'Exile', 'Vision'] },
  { name: 'St. Blaise', feastDate: '02-03', shortBio: 'A bishop and martyr, patron of throat ailments. He was arrested, and on the way to prison he saved a boy choking on a fishbone.', struggles: ['Healing', 'Sickness', 'Martyrdom'] },
  { name: 'St. Valentine', feastDate: '02-14', shortBio: 'A priest and martyr who secretly married Christian couples. He is the patron of lovers — not the Hallmark version, but the kind that dies for what it loves.', struggles: ['Marriage', 'Love', 'Martyrdom', 'Courage'] },
  { name: 'St. Patrick', feastDate: '03-17', shortBio: 'A kidnapped slave who escaped Ireland, returned as a bishop, and converted a nation. He faced down druids with a staff and a prayer.', struggles: ['Calling', 'Forgiveness', 'Mission', 'Past wounds'], companionId: 'paul' },
  { name: 'St. George', feastDate: '04-23', shortBio: 'A Roman soldier martyred for refusing to renounce Christ. The dragon came later in legend — but the man was real, and he chose death over compromise.', struggles: ['Courage', 'Integrity', 'Career vs. faith', 'Martyrdom'] },
  { name: 'St. Rita of Cascia', feastDate: '05-22', shortBio: 'A wife, mother, then widow, then nun. She suffered an abusive marriage, lost her sons, and still became a saint of the impossible. She is the patron of lost causes.', struggles: ['Marriage', 'Abuse', 'Loss', 'Hopelessness'] },
  { name: 'St. Philip Neri', feastDate: '05-26', shortBio: 'The "Apostle of Rome" who founded the Oratory. He was known for joy, pranks, and holiness. He laughed his way to sanctity.', struggles: ['Joy', 'Sadness', 'Community', 'Humor'] },
  { name: 'St. Charles Lwanga', feastDate: '06-03', shortBio: 'A young Ugandan page who was burned alive for resisting the king\'s abuse. He and his companions died as teenagers — the first martyrs of sub-Saharan Africa.', struggles: ['Purity', 'Abuse', 'Courage', 'Youth'] },
  { name: 'St. Boniface', feastDate: '06-05', shortBio: 'The "Apostle of Germany" who chopped down the sacred oak of Thor and built a chapel from its wood. He was martyred by pirates.', struggles: ['Mission', 'Courage', 'Reform', 'Opposition'] },
  { name: 'St. Camillus de Lellis', feastDate: '07-18', shortBio: 'A gambling addict and soldier who lost everything, found Christ in a hospital, and founded an order to serve the sick. He carried the sick when no one else would.', struggles: ['Addiction', 'Gambling', 'Service', 'Reform'], companionId: 'paul' },
  { name: 'St. Mary Magdalene', feastDate: '07-22', shortBio: 'The first witness of the Resurrection. She had seven demons cast out and became the apostle to the apostles. She is the patron of repentant sinners.', struggles: ['Shame', 'Repentance', 'Grief', 'Conversion'], companionId: 'david' },
  { name: 'St. Bridget of Sweden', feastDate: '07-23', shortBio: 'A mystic, mother of eight, and widow who founded an order and received revelations from Christ. She was a wife, mother, and visionary — all at once.', struggles: ['Family', 'Widowhood', 'Vision', 'Balance'] },
  { name: 'St. Clare of Assisi', feastDate: '08-11', shortBio: 'A young noblewoman who fled an arranged marriage to follow Francis. She founded the Poor Clares and once repelled an army by holding the Eucharist.', struggles: ['Calling', 'Courage', 'Simplicity', 'Protection'] },
  { name: 'St. Lawrence', feastDate: '08-10', shortBio: 'A deacon who was grilled alive — and joked "Turn me over, I\'m done on this side." He is the patron of comedians and cooks. He died laughing.', struggles: ['Joy', 'Courage', 'Martyrdom', 'Humor'] },
  { name: 'St. Dominic', feastDate: '08-08', shortBio: 'The founder of the Order of Preachers. He was a quiet man who walked barefoot, sang, and taught truth. He gave the Church the Rosary as we know it.', struggles: ['Preaching', 'Truth', 'Simplicity', 'Prayer'] },
  { name: 'St. Edith Stein', feastDate: '08-09', shortBio: 'A Jewish philosopher who became a Carmelite nun and died at Auschwitz. She sought truth her whole life and found it in Christ — and in the gas chamber.', struggles: ['Doubt', 'Identity', 'Suffering', 'Intellectual pride'], companionId: 'augustine' },
  { name: 'St. Pius X', feastDate: '08-21', shortBio: 'A pope who lowered the age of First Communion and fought modernism. He was a poor country priest made pope — and never forgot the poor.', struggles: ['Reform', 'Tradition', 'Children', 'Poverty'] },
  { name: 'St. Rose of Lima', feastDate: '08-23', shortBio: 'The first saint of the Americas. A Dominican tertiary who lived in a garden shed, prayed for hours, and cared for the poor. She suffered in body and spirit.', struggles: ['Sickness', 'Isolation', 'Poverty', 'Prayer'] },
  { name: 'St. Gregory the Great', feastDate: '09-03', shortBio: 'A monk made pope against his will. He sent missionaries to England, reformed the liturgy, and wrote the Pastoral Rule. He wanted to be a monk, not a pope.', struggles: ['Reluctant leadership', 'Leadership', 'Reform', 'Overwhelm'], companionId: 'moses' },
  { name: 'St. Robert Bellarmine', feastDate: '09-17', shortBio: 'A Jesuit cardinal and theologian who defended the faith against Protestant reformers. He was a scholar and a saint — and he gave his furniture to the poor.', struggles: ['Intellectual pride', 'Tradition', 'Poverty', 'Debate'], companionId: 'augustine' },
  { name: 'St. Vincent de Paul', feastDate: '09-27', shortBio: 'A priest who was captured by pirates, enslaved, and freed. He founded the Vincentians and the Daughters of Charity to serve the poorest of the poor.', struggles: ['Service', 'Captivity', 'Poverty', 'Reform'] },
  { name: 'St. Wenceslaus', feastDate: '09-28', shortBio: 'A duke of Bohemia who was murdered by his brother for being too Christian. He was a ruler who knelt to serve — and died for it.', struggles: ['Leadership', 'Family betrayal', 'Service', 'Martyrdom'] },
  { name: 'St. Jerome', feastDate: '09-30', shortBio: 'The scholar who translated the Bible into Latin — the Vulgate. He was brilliant, irascible, and lived in a cave in Bethlehem with a lion.', struggles: ['Intellectual pride', 'Anger', 'Study', 'Solitude'], companionId: 'augustine' },
  { name: 'St. Teresa of Avila', feastDate: '10-15', shortBio: 'The Carmelite reformer and mystic who wrote the Interior Castle. She battled illness and opposition — and became a Doctor of the Church.', struggles: ['Burnout', 'Opposition', 'Prayer', 'Reform'], quote: 'Let nothing disturb you, let nothing frighten you.' },
  { name: 'St. Margaret Mary Alacoque', feastDate: '10-16', shortBio: 'A Visitation nun who received visions of the Sacred Heart. She was mocked and disbelieved — and the devotion spread worldwide.', struggles: ['Rejection', 'Doubt', 'Vision', 'Perseverance'] },
  { name: 'St. Jude', feastDate: '10-28', shortBio: 'The patron of lost causes. He is the saint for the hopeless — because he knows what it means to be forgotten and still faithful.', struggles: ['Hopelessness', 'Despair', 'Lost causes'] },
  { name: 'St. Martin de Porres', feastDate: '11-03', shortBio: 'A Dominican lay brother in Lima — the illegitimate son of a freed slave. He healed the sick, bilocated, and was known for radical humility.', struggles: ['Racism', 'Identity', 'Humility', 'Service'] },
  { name: 'St. Charles Borromeo', feastDate: '11-04', shortBio: 'A cardinal who reformed the Church after the Council of Trent. He sold his fortune to feed the poor during a famine and walked barefoot in processions.', struggles: ['Reform', 'Wealth', 'Leadership', 'Tradition'] },
  { name: 'St. Martin of Tours', feastDate: '11-11', shortBio: 'A Roman soldier who cut his cloak in half to share with a beggar — who turned out to be Christ. He left the army and became a bishop.', struggles: ['Generosity', 'Conscience', 'Career vs. faith', 'Courage'] },
  { name: 'St. Albert the Great', feastDate: '11-15', shortBio: 'A Dominican bishop and scientist — the teacher of Aquinas. He wrote on botany, zoology, and theology. He proved that faith and science are friends.', struggles: ['Intellectual pride', 'Science vs. faith', 'Teaching', 'Humility'], companionId: 'augustine' },
  { name: 'St. Elizabeth of Hungary', feastDate: '11-17', shortBio: 'A princess who built a hospital and served the sick with her own hands. Her husband died on crusade and she was cast out — she kept serving.', struggles: ['Widowhood', 'Wealth', 'Service', 'Loss'] },
  { name: 'St. Cecilia', feastDate: '11-22', shortBio: 'A Roman martyr and patron of musicians. She sang to God in her heart as she was led to death. She is the saint of music and courage.', struggles: ['Courage', 'Music', 'Purity', 'Martyrdom'] },
  { name: 'St. Andrew', feastDate: '11-30', shortBio: 'The first apostle called — Peter\'s brother. He was crucified on an X-shaped cross and preached from it until he died. He is the patron of fishermen.', struggles: ['Calling', 'Courage', 'Martyrdom', 'Brotherhood'], companionId: 'peter' },
  { name: 'St. Francis Xavier', feastDate: '12-03', shortBio: 'A Jesuit missionary who baptized tens of thousands in India, Indonesia, and Japan. He died waiting to enter China. He was Ignatius\'s roommate.', struggles: ['Mission', 'Endurance', 'Homesickness', 'Zeal'], companionId: 'paul' },
  { name: 'St. Nicholas', feastDate: '12-06', shortBio: 'The bishop of Myra who punched a heretic and gave gold to poor girls. The real Santa Claus was a fighter and a giver.', struggles: ['Generosity', 'Justice', 'Children', 'Courage'] },
  { name: 'Immaculate Conception', feastDate: '12-08', shortBio: 'The feast of Mary, preserved from original sin from the first moment of her existence. She is the woman clothed with the sun.', struggles: ['Purity', 'Trust', 'Vocation', 'Humility'] },
  { name: 'Our Lady of Guadalupe', feastDate: '12-12', shortBio: 'Mary appeared to Juan Diego, a poor indigenous man, and left her image on his tilma. She is the patroness of the Americas and the unborn.', struggles: ['Doubt', 'Smallness', 'Trust', 'Mission'] },
  { name: 'St. John of the Cross', feastDate: '12-14', shortBio: 'The Carmelite mystic who was imprisoned by his own brothers and wrote the Dark Night in a dark cell. He is the poet of the soul\'s ascent.', struggles: ['Depression', 'Darkness', 'Isolation', 'Spiritual dryness'], quote: 'He who climbs never stops going from beginning to beginning.' },
  { name: 'St. Peter Canisius', feastDate: '12-21', shortBio: 'A Jesuit who defended the faith in Germany after the Reformation. He wrote catechisms that taught a generation. He was gentle and relentless.', struggles: ['Tradition', 'Teaching', 'Opposition', 'Perseverance'], companionId: 'ignatius' },
  // ─── Additional male saints for the rotation ───
  { name: 'St. Sebastian', feastDate: '01-20', shortBio: 'A Roman soldier who secretly served Christ until he was found out, shot full of arrows, and left for dead — then recovered and confronted the emperor again. He is the patron of athletes and soldiers.', struggles: ['Courage', 'Double life', 'Perseverance', 'Physical suffering'] },
  { name: 'St. Isidore the Farmer', feastDate: '05-15', shortBio: 'A poor farm laborer who prayed while he plowed. Angels were seen plowing beside him when he stopped to pray. He is the patron of farmers and workers — ordinary men doing ordinary work for God.', struggles: ['Work', 'Poverty', 'Routine', 'Hidden holiness'], quote: 'The plow is my prayer.' },
  { name: 'St. Louis IX', feastDate: '08-25', shortBio: 'King of France, father of eleven, crusader, and a man who washed the feet of the poor. He administered justice under an oak tree in the forest. A king who served.', struggles: ['Leadership', 'Fatherhood', 'Justice', 'Power'] },
  { name: 'St. Kaleb of Ethiopia', feastDate: '10-24', shortBio: 'A king of Ethiopia who answered the call to defend Christians being persecuted in Arabia. He abdicated, became a monk, and lived in a cave for the rest of his life.', struggles: ['Leadership', 'Mission', 'Letting go', 'Reinvention'] },
  { name: 'St. Josemaría Escrivá', feastDate: '06-26', shortBio: 'A priest who taught that ordinary work is a path to holiness. He founded Opus Dei and told men: you do not need to leave the world to find God — find Him in your desk, your kitchen, your commute.', struggles: ['Work', 'Vocation', 'Ordinary life', 'Discipline'], quote: 'Don\'t let your life be sterile. Be useful.' },
  { name: 'Blessed Carlo Acutis', feastDate: '10-12', shortBio: 'A teenager who loved computers, coding, and the Eucharist. He documented Eucharistic miracles online and died of leukemia at 15. The first millennial blessed. He shows that holiness is possible in the digital age.', struggles: ['Technology', 'Youth', 'Purity', 'Purpose'], quote: 'The Eucharist is my highway to heaven.' },
  { name: 'St. Miguel Pro', feastDate: '11-23', shortBio: 'A Jesuit priest in Mexico who was executed by the government for his faith. His last words, arms outstretched like a cross: "Viva Cristo Rey!" He died laughing.', struggles: ['Persecution', 'Courage', 'Martyrdom', 'Joy'], quote: 'Viva Cristo Rey!' },
  { name: 'St. Polycarp', feastDate: '02-23', shortBio: 'A disciple of the Apostle John, bishop of Smyrna, martyred at 86. They tried to burn him at the stake but the fire would not touch him. He is the bridge between the apostles and the early Church.', struggles: ['Tradition', 'Persecution', 'Old age', 'Faithfulness'], quote: 'Eighty and six years have I served Him, and He never did me wrong.' },
  { name: 'St. Aloysius Gonzaga', feastDate: '06-21', shortBio: 'A young nobleman who gave up a fortune to join the Jesuits. He died at 23 caring for plague victims. He is the patron of youth and AIDS sufferers.', struggles: ['Purity', 'Youth', 'Sacrifice', 'Calling'] },
  { name: 'St. Longinus', feastDate: '03-15', shortBio: 'The Roman centurion who pierced Christ\'s side with a spear and, seeing the blood and water, declared "Truly this was the Son of God." A soldier who found faith at the cross.', struggles: ['Conversion', 'Violence', 'Doubt', 'Finding faith'] },
  { name: 'St. Eustace', feastDate: '09-20', shortBio: 'A Roman general who saw a stag with a cross between its antlers while hunting. He converted, lost everything, and was martyred with his family. The patron of hunters and difficult times.', struggles: ['Conversion', 'Loss', 'Family', 'Perseverance'] },
  { name: 'St. Meinrad', feastDate: '01-21', shortBio: 'A hermit who lived in a forest in Switzerland. He was murdered by robbers who thought he had treasure — he had only a few books. He is the patron of hermits and hospitality.', struggles: ['Solitude', 'Violence', 'Simplicity', 'Forgiveness'] },
  { name: 'St. Josaphat', feastDate: '11-12', shortBio: 'A Ruthenian archbishop martyred in 1623 for working to heal the split between East and West. He is the patron of Christian unity — bought with his own blood.', struggles: ['Unity', 'Courage', 'Persecution', 'Reconciliation'] },
  { name: 'St. Frances Xavier Cabrini', feastDate: '11-13', shortBio: 'An Italian nun who crossed the Atlantic in 1889 and built schools, hospitals, and orphanages for immigrants across America. She was the first United States citizen to be canonized, and is the patron of immigrants.', struggles: ['Immigrants', 'Perseverance', 'Work', 'Trust'] },
  { name: 'Presentation of the Blessed Virgin Mary', feastDate: '11-21', shortBio: 'The feast of the child Mary presented in the Temple, offered wholly to God by her parents. It honours the complete gift of self her whole life would become.', struggles: ['Consecration', 'Obedience', 'Trust', 'Offering'] },
  { name: 'Sts. Andrew Dung-Lac and Companions', feastDate: '11-24', shortBio: 'A Vietnamese priest beheaded in 1839 for refusing to renounce Christ — one of the 117 martyrs of Vietnam. Arrested and ransomed once before, he returned to his flock knowing the cost.', struggles: ['Persecution', 'Courage', 'Martyrdom', 'Perseverance'] },
  { name: 'Dedication of the Basilicas of Sts. Peter and Paul', feastDate: '11-18', shortBio: 'The feast of the dedication of Rome\'s two great apostolic basilicas — St. Peter\'s on the Vatican hill and St. Paul\'s outside the walls — raised over the tombs of the apostles.', struggles: ['Tradition', 'Remembrance', 'Perseverance'] },
  { name: 'St. Clement I', feastDate: '11-23', shortBio: 'The fourth pope, a successor of Peter who wrote to settle a quarrel in Corinth. Exiled to the Crimea under Trajan, he was martyred there — tradition says drowned with an anchor at his neck.', struggles: ['Unity', 'Persecution', 'Leadership', 'Exile'] },
  { name: 'St. Columban', feastDate: '11-23', shortBio: 'An Irish monk who left his homeland for good and carried the faith across Gaul and Italy, founding monasteries at Luxeuil and Bobbio. He was blunt with kings and tender with his monks.', struggles: ['Mission', 'Exile', 'Discipline', 'Courage'] },
  { name: 'St. Juan Diego', feastDate: '12-09', shortBio: 'A poor Aztec convert on whose cloak Our Lady of Guadalupe left her image in 1531. He asked to be excused as too small for the task — and was chosen anyway.', struggles: ['Smallness', 'Humility', 'Doubt', 'Trust'] },
  { name: 'St. Thomas Becket', feastDate: '12-29', shortBio: 'The chancellor turned Archbishop of Canterbury who defended the Church\'s liberty against his friend King Henry II. He was murdered by knights in his own cathedral in 1170.', struggles: ['Conscience', 'Integrity', 'Career vs. faith', 'Courage'] },
  { name: 'St. Sylvester I', feastDate: '12-31', shortBio: 'The pope who led the Church out of the catacombs into the peace of Constantine. Under him the great basilicas of Rome began to rise.', struggles: ['Leadership', 'Transition', 'Diplomacy', 'Perseverance'] },
  { name: 'St. Homobonus', feastDate: '11-13', shortBio: 'A merchant and tailor from Cremona who used his business profits to feed the poor. He is the patron of business people and tailors — proof that commerce and holiness are not enemies.', struggles: ['Work', 'Generosity', 'Business ethics', 'Wealth'], quote: 'I am not the owner of these goods — only the steward.' },
  { name: 'St. Adolf', feastDate: '06-30', shortBio: 'A monk in Spain who refused to renounce his faith before the Moors and was martyred. He chose his faith over his life and his name.', struggles: ['Persecution', 'Identity', 'Courage', 'Martyrdom'] },
  { name: 'St. Gerard', feastDate: '10-16', shortBio: 'A lay brother known as the patron of expectant mothers. He was falsely accused, cleared by a nun\'s testimony, and died of tuberculosis at 29. He is the saint for men who have been falsely accused.', struggles: ['False accusation', 'Sickness', 'Innocence', 'Patience'] },
  { name: 'St. Paul Miki', feastDate: '02-06', shortBio: 'A Japanese Jesuit seminarian crucified with twenty-five companions in Nagasaki. He preached forgiveness from the cross. He is the patron of Japan and a witness to courage under pressure.', struggles: ['Persecution', 'Forgiveness', 'Martyrdom', 'Preaching'], quote: 'I ask forgiveness of all who have aided in my death.' },
  { name: 'St. Roch', feastDate: '08-16', shortBio: 'A pilgrim who ministered to plague victims until he caught the plague himself. He survived and is the patron of the sick and those who care for them. He gave his health to serve others.', struggles: ['Sickness', 'Service', 'Isolation', 'Self-sacrifice'] },
  { name: 'St. Conrad of Parzham', feastDate: '04-21', shortBio: 'A porter at a Franciscan friary for forty-one years. He opened the door to the poor and never turned anyone away. He is the patron of doorkeepers — the holiness of small, faithful service.', struggles: ['Routine', 'Hidden holiness', 'Patience', 'Service'], quote: 'I must go — someone is waiting at the door.' },
  { name: 'St. Bruno', feastDate: '10-06', shortBio: 'The founder of the Carthusian order, the strictest monks in the Church. He left a brilliant career to live in silence in the Alps. He is the patron of those who seek silence in a loud world.', struggles: ['Silence', 'Solitude', 'Career vs. calling', 'Overwhelm'], quote: 'While the world changes, the cross stands firm.' },
  { name: 'St. Gabriel Possenti', feastDate: '02-27', shortBio: 'A young Passionist seminarian known for his charm and holiness. He died at 24. He is the patron of young men, students, and seminarians. He shows that a short life can be a full one.', struggles: ['Youth', 'Purity', 'Calling', 'Sickness'] },
  { name: 'St. Otto of Bamberg', feastDate: '06-30', shortBio: 'A bishop and diplomat who evangelized Pomerania without violence. He used negotiation, patience, and example. He is the patron of those who build peace in difficult places.', struggles: ['Leadership', 'Patience', 'Mission', 'Diplomacy'] },
  { name: 'The Most Holy Name of Jesus', feastDate: '01-03', shortBio: 'The feast of the name given to the Child at his circumcision, the name the angel announced before he was conceived. Devotion to the Holy Name spread through the preaching of Bernardine of Siena in the fifteenth century.', struggles: ['Reverence', 'Prayer', 'Trust'] },
  { name: 'St. Raymond of Penyafort', feastDate: '01-07', shortBio: 'A Catalan Dominican who compiled the decretals of canon law for Pope Gregory IX. In his nineties he still served as confessor and adviser to kings and popes.', struggles: ['Study', 'Leadership', 'Perseverance', 'Justice'] },
  { name: 'St. Hilary of Poitiers', feastDate: '01-13', shortBio: 'A bishop of Poitiers who defended the divinity of Christ against the Arian emperors. Exiled to the East for his faith, he wrote his great work on the Trinity there.', struggles: ['Exile', 'Courage', 'Doubt', 'Perseverance'] },
  { name: 'St. Vincent', feastDate: '01-22', shortBio: 'A deacon of Saragossa martyred under Diocletian in 304. He was tortured to make him surrender the Scriptures and give up his bishop, and he refused both.', struggles: ['Persecution', 'Courage', 'Martyrdom', 'Faithfulness'] },
  { name: 'St. Marianne Cope', feastDate: '01-23', shortBio: 'A German-born Franciscan sister in New York who led her sisters to Hawaii in 1883 to care for leprosy patients. She worked on Molokai beside Father Damien and after his death, and never contracted the disease.', struggles: ['Service', 'Leadership', 'Sickness', 'Perseverance'] },
  { name: 'St. Angela Merici', feastDate: '01-27', shortBio: 'An Italian visionary who founded the Ursulines in 1535 to teach poor girls. She began the work in her fifties, in an age that gave women almost no public role.', struggles: ['Teaching', 'Calling', 'Perseverance', 'Vision'] },
  { name: 'St. Jerome Emiliani', feastDate: '02-08', shortBio: 'A Venetian soldier who was captured in war and freed after prayer to Our Lady. He spent the rest of his life founding orphanages for children left destitute by war and plague.', struggles: ['Conversion', 'Service', 'Poverty', 'Perseverance'] },
  { name: 'St. Josephine Bakhita', feastDate: '02-08', shortBio: 'A Sudanese woman kidnapped into slavery as a child and brought to Italy. Baptized as an adult, she became a Canossian sister and forgave the people who had enslaved her.', struggles: ['Forgiveness', 'Suffering', 'Trust', 'Slavery'] },
  { name: 'The Seven Holy Founders of the Servite Order', feastDate: '02-17', shortBio: 'Seven Florentine merchants who in 1233 left their businesses and families to live in prayer together on Monte Senario. Their order, the Servants of Mary, spread devotion to her sorrows across Europe.', struggles: ['Friendship', 'Letting go', 'Community', 'Calling'] },
  { name: 'St. Peter Damian', feastDate: '02-21', shortBio: 'A hermit of Fonte Avellana who became the fiercest reformer of the eleventh-century Church. Made a cardinal against his will, he spent his life fighting simony and calling clergy back to holiness.', struggles: ['Reform', 'Solitude', 'Zeal', 'Reluctant leadership'] },
  { name: 'St. Katharine Drexel', feastDate: '03-03', shortBio: 'A Philadelphia heiress who gave her fortune to found schools and missions for Native American and African American children. She founded the Sisters of the Blessed Sacrament and Xavier University in New Orleans.', struggles: ['Wealth', 'Generosity', 'Justice', 'Mission'] },
  { name: 'St. Casimir', feastDate: '03-04', shortBio: 'A prince of Poland who died at twenty-five, known for prayer, chastity, and care for the poor. He is the patron saint of Poland and Lithuania.', struggles: ['Purity', 'Youth', 'Family', 'Peace'] },
  { name: 'St. John of God', feastDate: '03-08', shortBio: 'A Portuguese bookseller in Granada who, after a breakdown and conversion, founded hospitals for the poor and sick. He carried patients on his own back and begged in the streets to feed them.', struggles: ['Conversion', 'Service', 'Suffering', 'Generosity'] },
  { name: 'St. Frances of Rome', feastDate: '03-09', shortBio: 'A Roman wife and mother who turned her palace into a hospital during plague and famine. She founded a community of women who served the poor while living in their own homes.', struggles: ['Marriage', 'Family', 'Service', 'Grief'] },
  { name: 'St. Cyril of Jerusalem', feastDate: '03-18', shortBio: 'A bishop of Jerusalem whose catechetical lectures to new converts still survive from the fourth century. He was exiled three times in the Arian controversies and returned each time.', struggles: ['Teaching', 'Exile', 'Perseverance', 'Tradition'] },
  { name: 'St. Turibius of Mongrovejo', feastDate: '03-23', shortBio: 'A Spanish archbishop of Lima who spent twenty-five years traveling his enormous diocese on foot. He learned the native languages, defended the indigenous people, and confirmed saints including Rose of Lima and Martin de Porres.', struggles: ['Mission', 'Leadership', 'Endurance', 'Justice'] },
  { name: 'St. Francis of Paola', feastDate: '04-02', shortBio: 'A Calabrian hermit who founded the Minim Order and lived on a diet of herbs and bread. Kings of France summoned him to court, and he spoke to them as plainly as to peasants.', struggles: ['Fasting', 'Simplicity', 'Solitude', 'Courage'] },
  { name: 'St. Isidore of Seville', feastDate: '04-04', shortBio: 'A bishop of Seville whose Etymologies gathered the knowledge of the ancient world into twenty books. He presided over councils that shaped the Church in Spain for centuries.', struggles: ['Study', 'Teaching', 'Leadership', 'Perseverance'] },
  { name: 'St. Vincent Ferrer', feastDate: '04-05', shortBio: 'A Dominican preacher who walked across Europe calling Christians to repentance during the Western Schism. Thousands came to hear him, and he worked for the unity of the Church until his death in Brittany.', struggles: ['Preaching', 'Zeal', 'Unity', 'Endurance'] },
  { name: 'St. Martin I', feastDate: '04-13', shortBio: 'A pope seized by imperial soldiers in the Lateran and carried off to exile in the Crimea. He had refused to bend the faith to the emperor, and he died of hunger and mistreatment in 655.', struggles: ['Persecution', 'Exile', 'Courage', 'Faithfulness'] },
  { name: 'St. Fidelis of Sigmaringen', feastDate: '04-24', shortBio: 'A lawyer who abandoned a successful practice to become a Capuchin friar. Sent to preach in Switzerland during the Reformation, he was beaten to death by a mob in 1622.', struggles: ['Career vs. faith', 'Preaching', 'Courage', 'Martyrdom'] },
  { name: 'St. Peter Chanel', feastDate: '04-28', shortBio: 'A French Marist priest martyred on the island of Futuna in 1841. He was the first martyr of Oceania, killed by the son-in-law of the king whose people he was slowly winning.', struggles: ['Mission', 'Perseverance', 'Martyrdom', 'Patience'] },
  { name: 'St. Louis de Montfort', feastDate: '04-28', shortBio: 'A French priest who preached total consecration to Jesus through Mary across western France. His True Devotion to Mary was lost for over a century and found again after his death.', struggles: ['Preaching', 'Rejection', 'Perseverance', 'Zeal'] },
  { name: 'St. Pius V', feastDate: '04-30', shortBio: 'A Dominican friar who became pope and carried out the reforms of the Council of Trent. He standardized the Mass, published the Catechism, and credited the victory at Lepanto to the Rosary.', struggles: ['Reform', 'Leadership', 'Tradition', 'Prayer'] },
  { name: 'St. Joseph the Worker', feastDate: '05-01', shortBio: 'The feast of Joseph as a working man, instituted by Pope Pius XII in 1955 for the first of May. It proclaims that ordinary labour, done well, is a path to holiness.', struggles: ['Work', 'Ordinary life', 'Fatherhood', 'Provision'] },
  { name: 'St. John of Ávila', feastDate: '05-10', shortBio: 'A Spanish priest whose letters and preaching reformed the clergy of Andalusia and guided saints. He counseled Teresa of Avila and John of God, and Pope Benedict XVI named him a Doctor of the Church.', struggles: ['Teaching', 'Preaching', 'Reform', 'Perseverance'] },
  { name: 'St. Damien de Veuster', feastDate: '05-10', shortBio: 'A Belgian priest who volunteered to serve the leper colony on Molokai in 1873. He contracted leprosy himself and died among the people he refused to leave.', struggles: ['Service', 'Sickness', 'Isolation', 'Self-sacrifice'] },
  { name: 'Sts. Nereus and Achilleus', feastDate: '05-12', shortBio: 'Roman soldiers who were converted to Christ and put to death for their faith. They were buried in the catacomb of Domitilla on the Via Ardeatina.', struggles: ['Conversion', 'Courage', 'Martyrdom'] },
  { name: 'St. Pancras', feastDate: '05-12', shortBio: 'A boy of fourteen martyred in Rome under Diocletian. He became one of the most beloved young martyrs of the early Church, patron of children and of oaths.', struggles: ['Youth', 'Courage', 'Martyrdom', 'Purity'] },
  { name: 'St. John I', feastDate: '05-18', shortBio: 'A pope sent by the Arian king Theodoric to negotiate in Constantinople. On his return the king imprisoned him at Ravenna, where he died in 526 from the hardship of the journey and captivity.', struggles: ['Persecution', 'Leadership', 'Endurance', 'Diplomacy'] },
  { name: 'St. Bernardine of Siena', feastDate: '05-20', shortBio: 'A Franciscan preacher who carried a banner of the Holy Name through the cities of Italy. His sermons drew such crowds that town squares had to be enlarged to hold them.', struggles: ['Preaching', 'Zeal', 'Reform', 'Humility'] },
  { name: 'St. Christopher Magallanes and Companions', feastDate: '05-21', shortBio: 'A Mexican priest shot by government troops in 1927 during the persecution of the Church. He was executed with his vicar and forgave the men who killed him.', struggles: ['Persecution', 'Forgiveness', 'Martyrdom', 'Courage'] },
  { name: 'St. Bede the Venerable', feastDate: '05-25', shortBio: 'An English monk whose Ecclesiastical History of the English People preserved the story of a nation\'s conversion. He spent his whole life in one monastery at Jarrow, translating and teaching until his final day.', struggles: ['Study', 'Teaching', 'Hidden holiness', 'Perseverance'] },
  { name: 'St. Gregory VII', feastDate: '05-25', shortBio: 'The monk Hildebrand, who as pope fought to free the Church from lay control. He faced down the emperor Henry IV at Canossa and died in exile for the reform he would not abandon.', struggles: ['Reform', 'Leadership', 'Exile', 'Courage'] },
  { name: 'St. Mary Magdalene de\' Pazzi', feastDate: '05-25', shortBio: 'A Florentine Carmelite mystic whose ecstasies were recorded by her sisters. She hid a life of intense prayer and suffering behind ordinary convent duties.', struggles: ['Prayer', 'Suffering', 'Hidden holiness', 'Perseverance'] },
  { name: 'St. Augustine of Canterbury', feastDate: '05-27', shortBio: 'A Roman monk sent by Pope Gregory the Great to evangelize the Anglo-Saxons. He landed in Kent in 597 and became the first Archbishop of Canterbury.', struggles: ['Mission', 'Fear', 'Leadership', 'Perseverance'] },
  { name: 'St. Paul VI', feastDate: '05-29', shortBio: 'The pope who brought the Second Vatican Council to its close and began the Church\'s modern pilgrim journeys. He wrote Humanae Vitae in 1968 and bore its controversy with patience.', struggles: ['Leadership', 'Reform', 'Suffering', 'Perseverance'] },
  { name: 'Sts. Marcellinus and Peter', feastDate: '06-02', shortBio: 'A Roman priest and an exorcist martyred together under Diocletian around 304. Constantine built a basilica over their tomb on the Via Labicana.', struggles: ['Courage', 'Martyrdom', 'Friendship'] },
  { name: 'St. Norbert', feastDate: '06-06', shortBio: 'A courtier converted when lightning threw him from his horse. He founded the Premonstratensian order at Prémontré and ended his life as Archbishop of Magdeburg.', struggles: ['Conversion', 'Preaching', 'Reform', 'Leadership'] },
  { name: 'St. Ephrem', feastDate: '06-09', shortBio: 'A Syrian deacon whose hymns earned him the title Harp of the Holy Spirit. He wrote poetry and commentary while serving the poor of Edessa through famine and plague.', struggles: ['Teaching', 'Music', 'Service', 'Humility'] },
  { name: 'St. Romuald', feastDate: '06-19', shortBio: 'An Italian nobleman who became a monk after witnessing a murder in his family. He spent his life founding and reforming hermitages, including Camaldoli, always moving on to seek a stricter solitude.', struggles: ['Solitude', 'Restlessness', 'Reform', 'Perseverance'] },
  { name: 'St. Paulinus of Nola', feastDate: '06-22', shortBio: 'A wealthy Roman senator who gave away his fortune and became bishop of Nola. His poems and letters to the great Christians of his age still survive.', struggles: ['Wealth', 'Generosity', 'Letting go', 'Friendship'] },
  { name: 'St. John Fisher', feastDate: '06-22', shortBio: 'The bishop of Rochester, the only English bishop who refused to accept Henry VIII as head of the Church. He was beheaded on Tower Hill in June 1535, days before Thomas More.', struggles: ['Conscience', 'Integrity', 'Courage', 'Martyrdom'] },
  { name: 'St. Cyril of Alexandria', feastDate: '06-27', shortBio: 'A patriarch of Alexandria who presided at the Council of Ephesus in 431. His defense of Mary as Mother of God fixed the Church\'s teaching on the person of Christ.', struggles: ['Debate', 'Leadership', 'Zeal', 'Tradition'] },
  { name: 'St. Junípero Serra', feastDate: '07-01', shortBio: 'A Mallorcan Franciscan who founded nine missions along the California coast. Despite a chronically injured leg, he walked thousands of miles between them into his seventies.', struggles: ['Mission', 'Endurance', 'Suffering', 'Perseverance'] },
  { name: 'St. Elizabeth of Portugal', feastDate: '07-04', shortBio: 'A queen of Portugal who made peace between warring kings of her own family. She spent her widowhood serving the poor and died on a journey to stop a war between her son and grandson.', struggles: ['Marriage', 'Family', 'Peace', 'Generosity'] },
  { name: 'St. Anthony Zaccaria', feastDate: '07-05', shortBio: 'A physician in Cremona who became a priest and founded the Barnabites. He promoted the Forty Hours devotion and frequent communion before dying at thirty-six.', struggles: ['Reform', 'Zeal', 'Youth', 'Perseverance'] },
  { name: 'St. Maria Goretti', feastDate: '07-06', shortBio: 'An Italian girl of eleven who died in 1902 resisting an assault by a farmhand named Alessandro Serenelli. On her deathbed she forgave him, and he later repented and attended her canonization beside her mother.', struggles: ['Purity', 'Forgiveness', 'Youth', 'Courage'] },
  { name: 'St. Augustine Zhao Rong and Companions', feastDate: '07-09', shortBio: 'A Chinese soldier who converted while guarding a captured missionary and was ordained a priest. He was martyred in 1815, one of the 120 martyrs of China honored with him.', struggles: ['Conversion', 'Persecution', 'Martyrdom', 'Courage'] },
  { name: 'St. Henry', feastDate: '07-13', shortBio: 'A Holy Roman Emperor who founded the diocese of Bamberg and strengthened the Church across Germany. He and his wife Cunigunde were famed for prayer and generosity to monasteries.', struggles: ['Leadership', 'Marriage', 'Power', 'Generosity'] },
  { name: 'St. Apollinaris', feastDate: '07-20', shortBio: 'The first bishop of Ravenna, sent there according to tradition by Saint Peter himself. He was beaten and expelled repeatedly for preaching and died from the wounds of a final attack.', struggles: ['Persecution', 'Endurance', 'Preaching', 'Martyrdom'] },
  { name: 'St. Lawrence of Brindisi', feastDate: '07-21', shortBio: 'A Capuchin friar who preached across Europe in the languages of the peoples he visited. He served as chaplain to imperial troops and rode before them at the battle of Székesfehérvár carrying a crucifix.', struggles: ['Preaching', 'Study', 'Courage', 'Diplomacy'] },
  { name: 'St. Sharbel Makhluf', feastDate: '07-24', shortBio: 'A Maronite monk and hermit of Lebanon who lived in near-total solitude at Annaya. After his death his tomb became a place of pilgrimage and reported healings for Christians and Muslims alike.', struggles: ['Solitude', 'Silence', 'Prayer', 'Hidden holiness'] },
  { name: 'St. Peter Chrysologus', feastDate: '07-30', shortBio: 'An archbishop of Ravenna whose brief, burning sermons earned him the name Chrysologus, golden-worded. Nearly two hundred of his homilies survive.', struggles: ['Preaching', 'Teaching', 'Leadership', 'Humility'] },
  { name: 'St. Eusebius of Vercelli', feastDate: '08-02', shortBio: 'The first bishop of Vercelli, exiled to the East for refusing to condemn Saint Athanasius. He brought the common life of clergy back with him to Italy, joining monastery to cathedral.', struggles: ['Exile', 'Courage', 'Leadership', 'Tradition'] },
  { name: 'St. Peter Julian Eymard', feastDate: '08-02', shortBio: 'A French priest who founded the Congregation of the Blessed Sacrament in 1856. He spent his life drawing people to eucharistic adoration and frequent communion.', struggles: ['Prayer', 'Perseverance', 'Zeal', 'Reform'] },
  { name: 'Dedication of the Basilica of St. Mary Major', feastDate: '08-05', shortBio: 'The feast of the dedication of the basilica of Saint Mary Major in Rome, the greatest church in the West dedicated to Our Lady. Tradition ties its founding to a miraculous snowfall on the Esquiline hill in August.', struggles: ['Tradition', 'Remembrance', 'Devotion'] },
  { name: 'St. Sixtus II and Companions', feastDate: '08-07', shortBio: 'A pope arrested while celebrating Mass in the catacombs in 258 and executed with four of his deacons. His deacon Lawrence followed him in martyrdom four days later.', struggles: ['Perseverance', 'Courage', 'Martyrdom', 'Leadership'] },
  { name: 'St. Cajetan', feastDate: '08-07', shortBio: 'An Italian priest who founded the Theatines to reform the clergy. In Naples he refused all fixed income and taught the poor to trust entirely in Providence.', struggles: ['Reform', 'Trust', 'Poverty', 'Perseverance'] },
  { name: 'St. Jane Frances de Chantal', feastDate: '08-12', shortBio: 'A French widow who, under the guidance of Saint Francis de Sales, founded the Order of the Visitation in 1610. She governed her sisters through plague, poverty, and opposition with steady gentleness.', struggles: ['Widowhood', 'Family', 'Perseverance', 'Gentleness'] },
  { name: 'St. Pontian', feastDate: '08-13', shortBio: 'A pope deported to the mines of Sardinia under the emperor Maximinus in 235. He resigned the papacy there so the Church could elect a successor, and died from the brutality of the mines.', struggles: ['Exile', 'Persecution', 'Leadership', 'Letting go'] },
  { name: 'St. Hippolytus', feastDate: '08-13', shortBio: 'A Roman priest and scholar who set himself up against the popes as a rival. Exiled to Sardinia alongside Pope Pontian, he was reconciled to the Church and died a martyr with him.', struggles: ['Intellectual pride', 'Reconciliation', 'Study', 'Martyrdom'] },
  { name: 'St. John Eudes', feastDate: '08-19', shortBio: 'A French missionary priest who preached across Normandy and founded seminaries to reform the clergy. He composed the first liturgical offices in honor of the Hearts of Mary and Jesus.', struggles: ['Preaching', 'Reform', 'Perseverance', 'Devotion'] },
  { name: 'St. Peter Claver', feastDate: '09-09', shortBio: 'A Spanish Jesuit who spent forty years meeting slave ships in the port of Cartagena. He boarded each ship with food and medicine and baptized hundreds of thousands of enslaved Africans.', struggles: ['Service', 'Justice', 'Endurance', 'Perseverance'] },
  { name: 'The Most Holy Name of Mary', feastDate: '09-12', shortBio: 'The feast of the Holy Name of Mary, spread after the victory at Vienna in 1683 was attributed to her intercession. It honours the name Christians have called on in danger for centuries.', struggles: ['Devotion', 'Trust', 'Perseverance'] },
  { name: 'St. Hildegard of Bingen', feastDate: '09-17', shortBio: 'A German abbess whose visions, recorded in Scivias, ranged from the structure of the cosmos to the fall of angels. She wrote on medicine and natural science, composed music, and rebuked emperors and popes by letter.', struggles: ['Vision', 'Courage', 'Study', 'Leadership'] },
  { name: 'St. Januarius', feastDate: '09-19', shortBio: 'A bishop of Benevento martyred under Diocletian around 305. His dried blood, kept in Naples cathedral, is famed for liquefying on his feast days.', struggles: ['Courage', 'Martyrdom', 'Perseverance', 'Faithfulness'] },
  { name: 'Sts. Cosmas and Damian', feastDate: '09-26', shortBio: 'Twin brothers and physicians in Arabia who treated the sick without accepting payment. They were martyred under Diocletian and became patrons of doctors and pharmacists.', struggles: ['Healing', 'Generosity', 'Martyrdom', 'Brotherhood'] },
  { name: 'St. Lawrence Ruiz and Companions', feastDate: '09-28', shortBio: 'A Filipino father and clerk who fled a false accusation aboard a ship to Japan. He was captured there and martyred at Nagasaki in 1637 with fifteen companions.', struggles: ['False accusation', 'Family', 'Martyrdom', 'Perseverance'] },
  { name: 'Bl. Marie Rose Durocher', feastDate: '10-06', shortBio: 'A Canadian woman who founded the Sisters of the Holy Names of Jesus and Mary in 1843 to teach the children of the poor. She began the work while serving as housekeeper in her brother\'s rectory.', struggles: ['Teaching', 'Hidden holiness', 'Perseverance', 'Service'] },
  { name: 'St. Denis and Companions', feastDate: '10-09', shortBio: 'The first bishop of Paris, beheaded on Montmartre under a third-century persecution. Tradition holds that he carried his head to the place where the basilica bearing his name now stands.', struggles: ['Mission', 'Courage', 'Martyrdom', 'Perseverance'] },
  { name: 'St. John Leonardi', feastDate: '10-09', shortBio: 'An Italian priest who founded the Clerks Regular of the Mother of God to reform clergy and teach catechism. He was exiled from his own city of Lucca for the reform and died nursing plague victims in Rome.', struggles: ['Reform', 'Teaching', 'Exile', 'Service'] },
  { name: 'St. John Henry Newman', feastDate: '10-09', shortBio: 'An Anglican scholar whose study of the early Church led him to Rome in 1845. He founded the Oratory in England and defended the role of conscience and the development of doctrine.', struggles: ['Conversion', 'Intellectual pride', 'Rejection', 'Perseverance'] },
  { name: 'St. John XXIII', feastDate: '10-11', shortBio: 'A pope elected at seventy-six as a caretaker who instead summoned the Second Vatican Council. Angelo Roncalli\'s warmth and humour made him beloved as Good Pope John.', struggles: ['Leadership', 'Reform', 'Joy', 'Old age'] },
  { name: 'St. Callistus I', feastDate: '10-14', shortBio: 'A former slave who rose to manage the Church\'s first official cemetery in Rome and then became pope. He was attacked for readmitting repentant sinners to communion and died in a riot in 222.', struggles: ['Forgiveness', 'Leadership', 'Persecution', 'Courage'] },
  { name: 'St. Hedwig', feastDate: '10-16', shortBio: 'A duchess of Silesia who founded monasteries and hospitals and cared for the poor. Widowed, she spent her last years in the Cistercian convent at Trzebnica that she had founded.', struggles: ['Widowhood', 'Generosity', 'Family', 'Perseverance'] },
  { name: 'St. John of Capistrano', feastDate: '10-23', shortBio: 'An Italian lawyer and governor who became a Franciscan and preached across Europe. At seventy he helped lead the defense of Belgrade against the Ottoman army in 1456 and died weeks later of plague.', struggles: ['Preaching', 'Career vs. faith', 'Courage', 'Old age'] },
  { name: 'St. Margaret of Scotland', feastDate: '11-16', shortBio: 'An English princess who became queen of Scotland and reformed its court and Church. She fed orphans at her own table and rose at midnight to pray.', struggles: ['Family', 'Leadership', 'Generosity', 'Reform'] },
  { name: 'St. Gertrude', feastDate: '11-16', shortBio: 'A Saxon nun of Helfta whose visions of Christ\'s love fill her book The Herald of Divine Love. She is a patron of the Holy Souls and a forerunner of devotion to the Sacred Heart.', struggles: ['Prayer', 'Vision', 'Perseverance', 'Devotion'] },
  { name: 'St. Rose Philippine Duchesne', feastDate: '11-18', shortBio: 'A French sister who crossed the Atlantic in 1818 and founded the first free school west of the Mississippi. The Potawatomi people she served in Kansas called her the woman who prays always.', struggles: ['Mission', 'Perseverance', 'Prayer', 'Exile'] },
  { name: 'St. Catherine of Alexandria', feastDate: '11-25', shortBio: 'A young scholar of Alexandria who, by tradition, confounded the fifty philosophers sent to argue her out of her faith. She was martyred on a spiked wheel, which became her emblem.', struggles: ['Study', 'Courage', 'Youth', 'Martyrdom'] },
  { name: 'St. John Damascene', feastDate: '12-04', shortBio: 'A monk of Mar Saba near Jerusalem who defended the veneration of images during the iconoclast controversy. His work On the Orthodox Faith became a handbook of theology for East and West.', struggles: ['Tradition', 'Study', 'Perseverance', 'Debate'] },
  { name: 'Our Lady of Loreto', feastDate: '12-10', shortBio: 'The feast of Our Lady of Loreto, honouring the Holy House venerated in the Italian town of Loreto. Tradition holds it to be the house of Nazareth where the Annunciation took place, carried there in the thirteenth century.', struggles: ['Devotion', 'Trust', 'Remembrance'] },
  { name: 'St. Damasus I', feastDate: '12-11', shortBio: 'A pope who adorned the tombs of the martyrs in the Roman catacombs with verses of his own. He commissioned Saint Jerome to revise the Latin translation of the Scriptures.', struggles: ['Leadership', 'Tradition', 'Perseverance', 'Remembrance'] },
  { name: 'St. John of Kanty', feastDate: '12-23', shortBio: 'A professor of theology at Kraków who shared his salary and possessions with the poor. Robbed on a pilgrimage to Rome, he told the thieves about coins he had sewn into his cloak and gave them those as well.', struggles: ['Teaching', 'Generosity', 'Poverty', 'Humility'] },
  { name: 'St. Gregory Nazianzen', feastDate: '01-02', shortBio: 'A Cappadocian Father and bishop of Constantinople, famed as the Theologian for his sermons defending the Trinity. A close friend of Basil the Great, he preferred the quiet of study to the storms of office.', struggles: ['Study', 'Leadership', 'Friendship', 'Silence'] },
  { name: 'St. Elizabeth Ann Seton', feastDate: '01-04', shortBio: 'A New York widow who converted to Catholicism and founded the Sisters of Charity, opening the first free Catholic school in the United States. She is the first native-born American to be canonised a saint.', struggles: ['Widowhood', 'Conversion', 'Grief', 'Perseverance'] },
  { name: 'St. John Neumann', feastDate: '01-05', shortBio: 'A Bohemian-born Redemptorist missionary who became bishop of Philadelphia and built its Catholic school system parish by parish. He learned the languages of his immigrant flock and died at forty-eight, worn out by work.', struggles: ['Mission', 'Exhaustion', 'Immigrants', 'Service'] },
  { name: 'St. Agnes', feastDate: '01-21', shortBio: 'A Roman girl of twelve or thirteen who refused marriage and was martyred under Diocletian around 304. Her name is linked to the Latin word for lamb, and lambs are blessed in her honour each year on her feast.', struggles: ['Youth', 'Purity', 'Courage', 'Martyrdom'] },
  { name: 'The Conversion of St. Paul', feastDate: '01-25', shortBio: 'The feast of Saul\'s conversion on the road to Damascus, when the persecutor of the Church heard Christ\'s voice and became its apostle. The feast closes the Week of Prayer for Christian Unity.', struggles: ['Conversion', 'Changing direction', 'Zeal', 'Humility'] },
  { name: 'St. Timothy', feastDate: '01-26', shortBio: 'A companion and delegate of Paul who became bishop of Ephesus and received two of the apostle\'s letters. Tradition holds that he was martyred at Ephesus for opposing a pagan festival.', struggles: ['Mentoring', 'Mission', 'Youth', 'Discernment'] },
  { name: 'St. Titus', feastDate: '01-26', shortBio: 'A Greek convert and delegate of Paul who carried his letters and was left to govern the Church in Crete. Paul called him his brother and fellow worker.', struggles: ['Mission', 'Leadership', 'Service', 'Unity'] },
  { name: 'St. Agatha', feastDate: '02-05', shortBio: 'A Sicilian virgin martyred at Catania under Decius around 251, after refusing a Roman official\'s advances. She is invoked against fire, and her veil is said to have halted the lava of Etna.', struggles: ['Purity', 'Courage', 'Martyrdom', 'Suffering'] },
  { name: 'St. Scholastica', feastDate: '02-10', shortBio: 'The twin sister of Benedict, who founded a convent near Monte Cassino and met her brother yearly for a day of prayer. Her tears in prayer once kept him at her side through a storm, three days before she died.', struggles: ['Prayer', 'Family', 'Devotion', 'Perseverance'] },
  { name: 'St. Cyril', feastDate: '02-14', shortBio: 'A Byzantine monk who, with his brother Methodius, devised an alphabet for the Slavs and translated the liturgy into their tongue. He died in Rome in 869 and is honoured as an apostle of the Slavs.', struggles: ['Mission', 'Study', 'Unity', 'Perseverance'] },
  { name: 'St. Methodius', feastDate: '02-14', shortBio: 'A Byzantine missionary who, with his brother Cyril, evangelised the Slavs in their own language. He continued the work alone after Cyril\'s death, enduring imprisonment for the Slavonic liturgy.', struggles: ['Mission', 'Persecution', 'Unity', 'Endurance'] },
  { name: 'St. Perpetua', feastDate: '03-07', shortBio: 'A young mother of Carthage who wrote a prison diary before she was martyred in the arena in 203. She refused her father\'s pleas to renounce Christ, and her account is among the earliest writings by a Christian woman.', struggles: ['Family', 'Courage', 'Martyrdom', 'Perseverance'] },
  { name: 'St. Felicity', feastDate: '03-07', shortBio: 'An enslaved woman who gave birth in prison days before her martyrdom at Carthage in 203. She died beside Perpetua, whose faith she had come to share.', struggles: ['Slavery', 'Courage', 'Martyrdom', 'Trust'] },
  { name: 'St. John Baptist de la Salle', feastDate: '04-07', shortBio: 'A French priest who founded the Brothers of the Christian Schools and opened free schools for poor boys. He gave up his fortune and his canonry to train teachers and educate the working class.', struggles: ['Teaching', 'Reform', 'Poverty', 'Perseverance'] },
  { name: 'St. Stanislaus', feastDate: '04-11', shortBio: 'The bishop of Kraków who rebuked King Bolesław for his cruelties and was killed at the altar in 1079. He is the patron of Poland.', struggles: ['Speaking truth', 'Courage', 'Persecution', 'Leadership'] },
  { name: 'St. Athanasius', feastDate: '05-02', shortBio: 'The bishop of Alexandria who defended the divinity of Christ against Arianism and was exiled five times for it. His Life of Anthony spread monasticism through the Church.', struggles: ['Exile', 'Courage', 'Debate', 'Perseverance'] },
  { name: 'St. Philip', feastDate: '05-03', shortBio: 'An apostle from Bethsaida who brought Nathanael to Jesus and asked at the Last Supper to be shown the Father. Tradition holds that he was martyred at Hierapolis.', struggles: ['Doubt', 'Trust', 'Mission', 'Martyrdom'] },
  { name: 'St. James', feastDate: '05-03', shortBio: 'An apostle remembered as a kinsman of the Lord and the first bishop of Jerusalem. He was martyred there around 62, praying for his killers as he died.', struggles: ['Leadership', 'Prayer', 'Martyrdom', 'Endurance'] },
  { name: 'St. Matthias', feastDate: '05-14', shortBio: 'The disciple chosen by lot to take the place of Judas among the Twelve. He had witnessed the ministry of Jesus from the baptism to the Ascension.', struggles: ['Calling', 'Trust', 'Humility', 'Mission'] },
  { name: 'The Visitation', feastDate: '05-31', shortBio: 'The feast of Mary\'s visit to her cousin Elizabeth, when the unborn John the Baptist leapt for joy and Mary sang the Magnificat. It celebrates the meeting of the two mothers and the two children.', struggles: ['Joy', 'Family', 'Devotion', 'Trust'] },
  { name: 'St. Justin', feastDate: '06-01', shortBio: 'A philosopher of Samaria who came to Christ through his search for truth and wrote the earliest surviving accounts of how the Mass was celebrated. He was beheaded at Rome around 165 rather than sacrifice to the gods.', struggles: ['Big questions', 'Study', 'Courage', 'Martyrdom'] },
  { name: 'St. Barnabas', feastDate: '06-11', shortBio: 'A Levite from Cyprus who sold his field for the apostles, vouched for the converted Saul, and travelled with Paul on the first missionary journey. Scripture calls him the son of encouragement.', struggles: ['Generosity', 'Friendship', 'Mission', 'Reconciliation'] },
  { name: 'St. Irenaeus', feastDate: '06-28', shortBio: 'A bishop of Lyons formed by Polycarp, who had himself known the apostles, and the great opponent of Gnosticism. Named a Doctor of the Church in 2022, he is honoured as a martyr.', struggles: ['Study', 'Debate', 'Unity', 'Tradition'] },
  { name: 'St. Thomas', feastDate: '07-03', shortBio: 'The apostle who would not believe the Resurrection until he saw the wounds, and then cried, My Lord and my God. Tradition holds that he carried the Gospel as far as India.', struggles: ['Doubt', 'Trust', 'Mission', 'Courage'] },
  { name: 'St. Kateri Tekakwitha', feastDate: '07-14', shortBio: 'A Mohawk-Algonquin woman of New York who converted at nineteen, endured mockery for her faith, and devoted herself to prayer and penance. Canonised in 2012, she is known as the Lily of the Mohawks.', struggles: ['Persecution', 'Purity', 'Perseverance', 'Family'] },
  { name: 'St. Bonaventure', feastDate: '07-15', shortBio: 'A Franciscan friar and theologian who governed his order, wrote the life of Francis, and taught that creation leads the mind to God. He died a cardinal at the Council of Lyons in 1274.', struggles: ['Study', 'Leadership', 'Humility', 'Prayer'] },
  { name: 'St. Joachim', feastDate: '07-26', shortBio: 'The father of the Virgin Mary, honoured with his wife Anne in the Church\'s tradition. Scripture does not name him; the early Church remembered the couple as the righteous parents who raised the Mother of God.', struggles: ['Fatherhood', 'Family', 'Trust', 'Perseverance'] },
  { name: 'St. Anne', feastDate: '07-26', shortBio: 'The mother of the Virgin Mary, honoured with her husband Joachim in the Church\'s tradition. She is the patroness of mothers and grandmothers, and of Canada.', struggles: ['Family', 'Perseverance', 'Trust', 'Devotion'] },
  { name: 'St. Martha', feastDate: '07-29', shortBio: 'The sister of Mary and Lazarus of Bethany, who served the Lord at her table and confessed him as the Christ before he raised her brother. Jesus called her anxious about many things — and loved her.', struggles: ['Service', 'Family', 'Trust', 'Grief'] },
  { name: 'St. Mary of Bethany', feastDate: '07-29', shortBio: 'The sister of Martha and Lazarus, who sat at the feet of Jesus listening while her sister served. She anointed his feet and wiped them with her hair.', struggles: ['Devotion', 'Prayer', 'Family', 'Silence'] },
  { name: 'St. Lazarus', feastDate: '07-29', shortBio: 'The friend of Jesus whom he raised from the dead after four days in the tomb at Bethany. His rising was the sign that moved the authorities to plot the death of Jesus.', struggles: ['Friendship', 'Trust', 'Suffering', 'Family'] },
  { name: 'St. Alphonsus Liguori', feastDate: '08-01', shortBio: 'A Neapolitan lawyer who founded the Redemptorists and became the Church\'s great teacher of moral theology and prayer. He taught that those who pray are certainly saved, and he is the patron of confessors.', struggles: ['Prayer', 'Teaching', 'Reform', 'Perseverance'] },
  { name: 'Queenship of the Blessed Virgin Mary', feastDate: '08-22', shortBio: 'The feast of Mary as Queen of heaven and earth, kept a week after the Assumption. Instituted by Pius XII in 1954, it honours the mother who reigns beside her Son.', struggles: ['Devotion', 'Trust', 'Humility', 'Remembrance'] },
  { name: 'St. Bartholomew', feastDate: '08-24', shortBio: 'An apostle, often identified with Nathanael, who asked whether anything good could come from Nazareth and then confessed Jesus as Son of God. Tradition holds that he preached as far as Armenia and was flayed alive.', struggles: ['Doubt', 'Mission', 'Courage', 'Martyrdom'] },
  { name: 'The Passion of St. John the Baptist', feastDate: '08-29', shortBio: 'The feast of the beheading of John the Baptist, when a rash oath at a birthday feast cost the forerunner his head. He died as he had lived, bearing witness to the truth.', struggles: ['Speaking truth', 'Courage', 'Martyrdom', 'Integrity'] },
  { name: 'Nativity of the Blessed Virgin Mary', feastDate: '09-08', shortBio: 'The feast of the birth of the Virgin Mary, celebrated in the Church since at least the sixth century. Tradition names her parents as Joachim and Anne, and her birth as the dawn of salvation.', struggles: ['Joy', 'Trust', 'Devotion', 'Remembrance'] },
  { name: 'St. Cornelius', feastDate: '09-16', shortBio: 'A pope elected after a long vacancy in persecution who readmitted repentant Christians who had lapsed. He died in exile in 253 and is honoured as a martyr.', struggles: ['Forgiveness', 'Leadership', 'Persecution', 'Exile'] },
  { name: 'St. Cyprian', feastDate: '09-16', shortBio: 'The bishop of Carthage who held his Church together through persecution and plague, writing on its unity. He was beheaded in 258, answering his death sentence with thanks to God.', struggles: ['Leadership', 'Unity', 'Courage', 'Martyrdom'] },
  { name: 'St. Andrew Kim Tae-gŏn', feastDate: '09-20', shortBio: 'The first Korean-born Catholic priest, ordained in secret and martyred at twenty-five in the persecutions of 1846. He is honoured with Paul Chŏng Ha-sang and 101 companions.', struggles: ['Persecution', 'Youth', 'Courage', 'Martyrdom'] },
  { name: 'St. Paul Chŏng Ha-sang', feastDate: '09-20', shortBio: 'A Korean lay catechist who wrote to the Pope begging for priests for his persecuted Church. He was martyred in 1839 and canonised with Andrew Kim and their companions.', struggles: ['Perseverance', 'Mission', 'Courage', 'Martyrdom'] },
  { name: 'St. Ignatius of Antioch', feastDate: '10-17', shortBio: 'A bishop of Antioch who, condemned to the beasts at Rome, wrote seven letters on the road begging the Christians not to save him. He called himself the wheat of God, to be ground by the teeth of beasts into the pure bread of Christ.', struggles: ['Courage', 'Martyrdom', 'Unity', 'Endurance'] },
  { name: 'Dedication of the Lateran Basilica', feastDate: '11-09', shortBio: 'The feast of the dedication of the Lateran basilica in Rome, the cathedral of the Pope and mother and head of all churches in the city and the world. Consecrated in the fourth century, it is the oldest of Rome\'s great basilicas.', struggles: ['Tradition', 'Remembrance', 'Unity', 'Devotion'] },
  { name: 'St. Leo the Great', feastDate: '11-10', shortBio: 'The pope who met Attila the Hun and turned him back from Rome, and whose Tome on the two natures of Christ was acclaimed at Chalcedon. He taught the Church to remember the dignity of her children.', struggles: ['Leadership', 'Courage', 'Teaching', 'Debate'] },
];
